{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-Db9Pim/src/address.js","content":"/**
 * Cell address parsing and ordering.
 *
 * An address is one or two letters naming a column (A..Z, then AA..ZZ) and
 * one to three digits naming a row of at least 1.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/**
 * Parse a raw token as a cell address. Returns `{ col, row, key }` where
 * `col` is the upper-cased column letters, `row` is the numeric row, and
 * `key` is the canonical `COLROW` string used to index cells. Returns
 * `null` when the token is not a valid address.
 */
export function parseAddress(raw) {
  const m = ADDRESS_RE.exec(raw)
  if (!m) return null
  const col = m[1].toUpperCase()
  const row = Number.parseInt(m[2], 10)
  if (row < 1) return null
  return { col, row, key: `${col}${row}` }
}

/** Numeric ordering key for a column: A=1 .. Z=26, AA=27 .. ZZ=702. */
export function columnIndex(col) {
  if (col.length === 1) return col.charCodeAt(0) - 64
  const a = col.charCodeAt(0) - 65
  const b = col.charCodeAt(1) - 64
  return 26 + a * 26 + b
}

/** Compare two addresses: ascending column, then ascending row. */
export function compareAddresses(a, b) {
  const ca = columnIndex(a.col)
  const cb = columnIndex(b.col)
  if (ca !== cb) return ca - cb
  return a.row - b.row
}

/**
 * Expand a range between two corner addresses into every address it
 * covers, in ascending column then ascending row order, regardless of
 * which corner the range was written from.
 */
export function expandRange(a, b) {
  const colLo = Math.min(columnIndex(a.col), columnIndex(b.col))
  const colHi = Math.max(columnIndex(a.col), columnIndex(b.col))
  const rowLo = Math.min(a.row, b.row)
  const rowHi = Math.max(a.row, b.row)
  const cells = []
  for (let c = colLo; c <= colHi; c++) {
    const col = indexToColumn(c)
    for (let r = rowLo; r <= rowHi; r++) {
      cells.push({ col, row: r, key: `${col}${r}` })
    }
  }
  return cells
}

function indexToColumn(index) {
  if (index <= 26) return String.fromCharCode(64 + index)
  const rest = index - 27
  const first = Math.floor(rest / 26)
  const second = rest % 26
  return String.fromCharCode(65 + first) + String.fromCharCode(65 + second)
}
"}

