{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-Db9Pim/src/values.js","content":"/**
 * The value model shared by literals and formula evaluation: a value is a
 * number, text, a boolean, or an error (identified by its error token).
 */

export const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

export function num(value) {
  return { type: 'number', value }
}

export function text(value) {
  return { type: 'text', value }
}

export function bool(value) {
  return { type: 'bool', value }
}

export function err(token) {
  return { type: 'error', value: token }
}

/** Parse a literal cell content string into a value. */
export function parseLiteral(content) {
  if (content === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number.parseFloat(content))
  if (ERROR_TOKENS.has(content)) return err(content)
  return text(content)
}

/** Read a value as a number for arithmetic; text becomes #VALUE!. */
export function toArithNumber(v) {
  if (v.type === 'error') return v
  if (v.type === 'number') return v
  if (v.type === 'bool') return num(v.value ? 1 : 0)
  return err('#VALUE!')
}

function typeRank(v) {
  if (v.type === 'number') return 0
  if (v.type === 'text') return 1
  return 2
}

/** Compare two non-error values per the cross-type ordering rules. */
export function compareValues(a, b) {
  const ra = typeRank(a)
  const rb = typeRank(b)
  if (ra !== rb) return ra - rb
  if (a.type === 'number') return a.value - b.value
  if (a.type === 'text') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  const av = a.value ? 1 : 0
  const bv = b.value ? 1 : 0
  return av - bv
}

/** Round a finite number to ten significant digits, JS-print style. */
export function roundSignificant(x, digits = 10) {
  if (!Number.isFinite(x) || x === 0) return x
  return Number(x.toPrecision(digits))
}

/** Format a value for the `values` command. */
export function formatValue(v) {
  switch (v.type) {
    case 'number':
      return String(roundSignificant(v.value))
    case 'bool':
      return v.value ? 'TRUE' : 'FALSE'
    case 'error':
      return v.value
    default:
      return v.value
  }
}
"}

