{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-Db9Pim/src/formula.js","content":"/**
 * Lexer and recursive-descent parser for formula bodies (the text after the
 * leading `=`). `parseFormula` returns an AST on success or `null` when the
 * grammar rejects the text, which the caller turns into `#ERR!`.
 *
 * AST node shapes:
 *   { kind: 'num', value }
 *   { kind: 'bool', value }
 *   { kind: 'address', name }
 *   { kind: 'range', from, to }         -- only ever a call argument
 *   { kind: 'unary', op, expr }
 *   { kind: 'binary', op, left, right }
 *   { kind: 'call', name, args }
 */

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const ADDITIVE_OPS = new Set(['+', '-'])
const MULTIPLICATIVE_OPS = new Set(['*', '/'])

class LexError extends Error {}
class ParseError extends Error {}

function tokenize(source) {
  const tokens = []
  let i = 0
  while (i < source.length) {
    const c = source[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (/[0-9]/.test(c)) {
      const start = i
      while (i < source.length && /[0-9]/.test(source[i])) i++
      if (source[i] === '.' && /[0-9]/.test(source[i + 1] ?? '')) {
        i++
        while (i < source.length && /[0-9]/.test(source[i])) i++
      }
      tokens.push({ type: 'number', value: source.slice(start, i) })
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      const start = i
      while (i < source.length && /[A-Za-z0-9]/.test(source[i])) i++
      tokens.push({ type: 'ident', value: source.slice(start, i) })
      continue
    }
    const two = source.slice(i, i + 2)
    if (two === '<=' || two === '>=' || two === '<>') {
      tokens.push({ type: 'op', value: two })
      i += 2
      continue
    }
    if ('()^*/+-=<>,:'.includes(c)) {
      const type = c === '(' ? 'lparen' : c === ')' ? 'rparen' : c === ',' ? 'comma' : c === ':' ? 'colon' : 'op'
      tokens.push({ type, value: c })
      i++
      continue
    }
    throw new LexError(`unexpected character ${c}`)
  }
  return tokens
}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.next()
    if (!t || t.type !== type) throw new ParseError(`expected ${type}`)
    return t
  }

  atEnd() {
    return this.pos >= this.tokens.length
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek() && this.peek().type === 'op' && COMPARISON_OPS.has(this.peek().value)) {
      const op = this.next().value
      const right = this.parseAdditive()
      left = { kind: 'binary', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek() && this.peek().type === 'op' && ADDITIVE_OPS.has(this.peek().value)) {
      const op = this.next().value
      const right = this.parseMultiplicative()
      left = { kind: 'binary', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek() && this.peek().type === 'op' && MULTIPLICATIVE_OPS.has(this.peek().value)) {
      const op = this.next().value
      const right = this.parsePower()
      left = { kind: 'binary', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.peek() && this.peek().type === 'op' && this.peek().value === '^') {
      this.next()
      const right = this.parsePower()
