/** Raised for a sheet line that fails to parse; carries the CLI's message. */
export class SheetError extends Error {
  constructor(message) {
    super(message)
    this.name = 'SheetError'
  }
}

/**
 * Parse the sheet text into a `Map` from canonical address key (e.g. `A1`)
 * to `{ address, content }`, in declaration order. Throws `SheetError` on
 * the first line that fails to parse.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  lines.forEach((line, index) => {
    const lineNumber = index + 1
    const stripped = line.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) return

    const m = /^([^ \t]+)(?:[ \t]([\s\S]*))?$/.exec(stripped)
    const rawAddress = m[1]
    const content = m[2] ?? ''

    const address = parseAddress(rawAddress)
    if (!address) {
      throw new SheetError(`error: line ${lineNumber}: invalid cell address ${rawAddress}`)
    }
