import { parseFormula } from './formula.js'
import { num, bool, err, text, parseLiteral, toArithNumber, compareValues } from './values.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

// 'many' means one or more arguments; otherwise the exact count required.
const ARITY = { SUM: 'many', MIN: 'many', MAX: 'many', COUNT: 'many', AVG: 'many', ABS: 1, IF: 3 }

/** Evaluates every declared cell, memoizing results and detecting cycles. */
class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.visiting = new Set()
  }

  valueOf(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    if (this.visiting.has(key)) return err('#CYCLE!')
    const cell = this.cells.get(key)
    if (!cell) return num(0)
    this.visiting.add(key)
    const value = this.evaluateContent(cell.content)
    this.visiting.delete(key)
    this.memo.set(key, value)
    return value
  }

  evaluateContent(content) {
    if (content.startsWith('=')) {
      const ast = parseFormula(content.slice(1))
      if (!ast) return err('#ERR!')
      return this.evaluateAst(ast)
    }
    return parseLiteral(content)
  }

  resolveAddress(name) {
    const addr = parseAddress(name)
    if (!addr) return err('#REF!')
    return this.valueOf(addr.key)
  }

  /** Evaluate an argument node to the list of values it contributes. */
  evaluateArgList(node) {
    if (node.kind === 'range') {
      const from = parseAddress(node.from)
      const to = parseAddress(node.to)
      if (!from || !to) return [err('#REF!')]
      return expandRange(from, to).map((cell) => this.valueOf(cell.key))
    }
    return [this.evaluateAst(node)]
  }

  evaluateAst(node) {
    switch (node.kind) {
      case 'num':
        return num(node.value)
      case 'bool':
        return bool(node.value)
      case 'address':
        return this.resolveAddress(node.name)
      case 'unary':
        return this.evaluateUnary(node)
      case 'binary':
        return this.evaluateBinary(node)
      case 'call':
        return this.evaluateCall(node)
      default:
        return err('#ERR!')
    }
  }

  evaluateUnary(node) {
    const v = toArithNumber(this.evaluateAst(node.expr))
    if (v.type === 'error') return v
    const result = node.op === '-' ? -v.value : v.value
    return Number.isFinite(result) ? num(result) : err('#DIV/0!')
  }

  evaluateBinary(node) {
    const left = this.evaluateAst(node.left)
    const right = this.evaluateAst(node.right)
    if (COMPARISON_OPS.has(node.op)) {
      if (left.type === 'error') return left
      if (right.type === 'error') return right
      const cmp = compareValues(left, right)
      switch (node.op) {
        case '=':
          return bool(cmp === 0)
        case '<>':
          return bool(cmp !== 0)
        case '<':
          return bool(cmp < 0)
        case '<=':
          return bool(cmp <= 0)
        case '>':
          return bool(cmp > 0)
        case '>=':
          return bool(cmp >= 0)
      }
    }
    const ln = toArithNumber(left)
    if (ln.type === 'error') return ln
    const rn = toArithNumber(right)
    if (rn.type === 'error') return rn
    let result
    switch (node.op) {
      case '+':
        result = ln.value + rn.value
        break
      case '-':
        result = ln.value - rn.value
        break
      case '*':
        result = ln.value * rn.value
        break
      case '/':
        result = ln.value / rn.value
        break
      case '^':
        result = Math.pow(ln.value, rn.value)
        break
    }
    return Number.isFinite(result) ? num(result) : err('#DIV/0!')
  }

  evaluateCall(node) {
    const arity = ARITY[node.name]
    if (arity === undefined) return err('#NAME?')
    if (arity === 'many' ? node.args.length < 1 : node.args.length !== arity) return err('#ERR!')

    if (node.name === 'IF') return this.evaluateIf(node)

    const values = node.args.flatMap((arg) => this.evaluateArgList(arg))
    const firstError = values.find((v) => v.type === 'error')
    if (firstError) return firstError

    switch (node.name) {
      case 'ABS':
        return applyFinite((n) => Math.abs(n), toArithNumber(values[0]))
      case 'SUM':
        return reduceNumbers(values, (acc, n) => acc + n, 0)
      case 'MIN':
        return reduceNumbers(values, (acc, n, i) => (i === 0 ? n : Math.min(acc, n)), undefined)
      case 'MAX':
        return reduceNumbers(values, (acc, n, i) => (i === 0 ? n : Math.max(acc, n)), undefined)
      case 'AVG': {
        const sum = reduceNumbers(values, (acc, n) => acc + n, 0)
        if (sum.type === 'error') return sum
        return applyFinite((x) => x, num(sum.value / values.length))
      }
      case 'COUNT':
        return num(values.filter((v) => v.type === 'number').length)
      default:
        return err('#NAME?')
    }
  }

  evaluateIf(node) {
    const condValues = this.evaluateArgList(node.args[0])
    const cond = condValues[0]
    if (cond.type === 'error') return cond
    let condBool
    if (cond.type === 'bool') condBool = cond.value
    else if (cond.type === 'number') condBool = cond.value !== 0
    else return err('#VALUE!')
    const branch = condBool ? node.args[1] : node.args[2]
    return this.evaluateArgList(branch)[0]
  }
