function reduceNumbers(values, reducer, initial) {
  let acc = initial
  for (let i = 0; i < values.length; i++) {
    const n = toArithNumber(values[i])
    if (n.type === 'error') return n
    acc = reducer(acc, n.value, i)
  }
  return applyFinite((x) => x, num(acc))
}

function applyFinite(fn, v) {
  if (v.type === 'error') return v
  const result = fn(v.value)
  return Number.isFinite(result) ? num(result) : err('#DIV/0!')
}

