/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { compareAddresses } from './address.js'
import { collectDeps } from './deps.js'
import { evaluateSheet } from './evaluate.js'
import { parseFormula } from './formula.js'
import { parseSheet, SheetError } from './sheet.js'
import { formatValue } from './values.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('error: usage: cli.js values|deps')
    return
  }

  const input = await readStdin()
  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(e.message)
      return
    }
    throw e
  }

  const orderedKeys = [...cells.keys()].sort((a, b) => compareAddresses(cells.get(a).address, cells.get(b).address))

  if (mode === 'values') {
    const values = evaluateSheet(cells)
    let out = ''
    for (const key of orderedKeys) out += `${key}=${formatValue(values.get(key))}\n`
    process.stdout.write(out)
    return
  }

  let out = ''
  for (const key of orderedKeys) {
    const cell = cells.get(key)
    let deps = []
    if (cell.content.startsWith('=')) {
      const ast = parseFormula(cell.content.slice(1))
      if (ast) deps = collectDeps(ast)
    }
    out += `${key}:${deps.map((d) => ` ${d.key}`).join('')}\n`
  }
  process.stdout.write(out)
}

main()
"}

